def table(headers, rows):
    fmt='l'+'r'*(len(headers)-1)
    header='&'.join(r'\text{'+h+'}' for h in headers)+r'\\\hline'
    content=['&'.join([r'\text{'+name+'}',*(str(v) for v in values)]) for name,values in rows]
    return '$$\\begin{array}{'+fmt+'}'+header+'\\\\'.join(content)+'\\end{array}$$'


